import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/forgot-password');
  });

  test('should display confirmation message after successful password reset', async ({ page }) => {
    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('user@example.com');

    // Locate and click reset button using getByRole
    const resetBtn = page.getByRole('button', { name: /reset password/i });
    await resetBtn.click();

    // Wait for confirmation message to appear
    const confirmationMessage = page.getByText(/password reset link sent/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify success message contains expected text
    await expect(confirmationMessage).toContainText('Password reset link sent to user@example.com');

    // Verify success class is applied
    const successClass = page.locator('[data-testid="success-message"]');
    await expect(successClass).toHaveClass(/success-message/);

    // Verify reset form is no longer visible
    const emailInputAfterReset = page.getByLabel('Email address');
    await expect(emailInputAfterReset).not.toBeVisible();
  });

  test('should not display confirmation message when email is invalid', async ({ page }) => {
    // Locate and fill email input with invalid format using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('invalid-email');

    // Locate and click reset button using getByRole
    const resetBtn = page.getByRole('button', { name: /reset password/i });
    await resetBtn.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/invalid email format/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message contains expected text
    await expect(errorMessage).toContainText('Please enter a valid email address');

    // Verify confirmation message does not exist
    const confirmationMessage = page.getByText(/password reset link sent/i);
    await expect(confirmationMessage).not.toBeVisible();

    // Verify reset form is still visible
    const emailInputAfterError = page.getByLabel('Email address');
    await expect(emailInputAfterError).toBeVisible();
  });
});
